import{_ as h,C as c,o,c as l,a2 as n,b as a,w as t,a as i,E as r,aa as d}from"./chunks/framework.m2m6h9S0.js";const b=JSON.parse('{"title":"Accounts","description":"","frontmatter":{},"headers":[],"relativePath":"docs/accounts.md","filePath":"docs/accounts.md"}'),u={name:"docs/accounts.md"};function g(p,e,w,m,y,f){const s=c("Mermaid");return o(),l("div",null,[e[2]||(e[2]=n('<h1 id="accounts" tabindex="-1">Accounts <a class="header-anchor" href="#accounts" aria-label="Permalink to &quot;Accounts&quot;">​</a></h1><p>What a guest gets by signing up, and what the server and the phones do with an <strong>account</strong>. This is the spec for <a href="https://github.com/tkint/coach-poulpy/issues/25" target="_blank" rel="noreferrer">#25</a>; the tickets built from it are its sub-issues. How a request is authenticated is in <a href="./the-api">The API</a> and <a href="./adr/0020-every-credential-resolves-to-one-caller">ADR 0020</a>; the phone stays the source of truth (<a href="./adr/0001-local-first-phone-is-the-source-of-truth">ADR 0001</a>).</p><h2 id="signing-up-and-signing-in" tabindex="-1">Signing up and signing in <a class="header-anchor" href="#signing-up-and-signing-in" aria-label="Permalink to &quot;Signing up and signing in&quot;">​</a></h2><ul><li><strong>Email and password only, for now.</strong> Sign in with Apple and Google come later, each as one new authenticator; no route changes. Passwords are hashed with Argon2id.</li><li><strong>The email is confirmed before any data leaves the phone.</strong> Signing up sends a link; until it is tapped, the phone keeps working as a guest and uploads nothing. A typo in the address can never tie health data to someone else&#39;s mailbox.</li><li><strong>The link can be opened anywhere</strong>, on the phone or on a computer. While Check your email is on screen the phone asks every 3 seconds whether it was opened, and on each app open once; when it was, the phone signs in with the password it kept and moves on to Email confirmed (<a href="https://github.com/tkint/coach-poulpy/issues/319" target="_blank" rel="noreferrer">#319</a>). It asks with a random key sent at sign-up rather than by trying the password, which would count towards the 5 refused sign-ins that lock an address. The key follows only the link mailed with it, so it never tells who owns an address.</li><li><strong>Health data consent is asked at sign-up</strong>, with a link to what is stored and why.</li><li><strong>Forgotten password</strong>: the person asks for a reset link by email and chooses a new password; every phone is signed out.</li><li><strong>Mail goes out over plain SMTP</strong> to an EU provider set in the server&#39;s settings, so the provider can change without a code change.</li></ul><h2 id="the-phone-and-the-account" tabindex="-1">The phone and the account <a class="header-anchor" href="#the-phone-and-the-account" aria-label="Permalink to &quot;The phone and the account&quot;">​</a></h2>',5)),(o(),a(d,null,{default:t(()=>[r(s,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20guest(%5B%22Guest%22%5D)%20--%20%22sign%20up%22%20--%3E%20pending%5B%22Account%2C%20email%20not%20confirmed%3Cbr%2F%3Ephone%20still%20a%20guest%22%5D%0A%20%20%20%20pending%20--%20%22tap%20the%20link%22%20--%3E%20synced%5B%22Signed%20in%3Cbr%2F%3Ephone%20uploads%2C%20then%20syncs%22%5D%0A%20%20%20%20guest%20--%20%22sign%20in%20to%20an%20existing%20account%22%20--%3E%20merged%5B%22Signed%20in%3Cbr%2F%3Eguest%20data%20merged%20into%20the%20account%22%5D%0A%20%20%20%20synced%20--%20%22sign%20out%22%20--%3E%20cleared(%5B%22Empty%20guest%22%5D)%0A%20%20%20%20merged%20--%20%22sign%20out%22%20--%3E%20cleared%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[i(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=n('<ul><li><strong>The first upload keeps every id</strong> (<a href="./adr/0005-ids-are-uuidv7-made-on-the-device">ADR 0005</a>).</li><li><strong>Signing in on a phone that has guest data merges it</strong> into the account. Ids never collide and sync keeps both edits (<a href="./adr/0006-sync-keeps-both-edits">ADR 0006</a>), so nothing is lost or overwritten.</li><li><strong>Signing out clears the phone once everything is uploaded.</strong> If some changes can&#39;t be uploaded (no connection), the phone says so and lets the person wait or sign out anyway. The phone then starts again as an empty guest, so the next person on a shared phone sees nothing.</li></ul><h2 id="sync" tabindex="-1">Sync <a class="header-anchor" href="#sync" aria-label="Permalink to &quot;Sync&quot;">​</a></h2><p>Phones sync through the account with two calls, push and pull (<a href="./adr/0006-sync-keeps-both-edits">ADR 0006</a>, <a href="./adr/0025-the-phone-forks-a-conflicting-workout-and-the-server-counts-changes">ADR 0025</a>). Both need the <code>sync</code> scope, so only the apps can call them.</p>',3)),(o(),a(d,null,{default:t(()=>[r(s,{id:"mermaid-68",class:"mermaid",graph:"sequenceDiagram%0A%20%20%20%20participant%20P%20as%20Phone%0A%20%20%20%20participant%20S%20as%20Server%0A%20%20%20%20P-%3E%3ES%3A%20GET%20%2Fapi%2Fv1%2Fsync%2Fpull%3Fcursor%3D41%0A%20%20%20%20S--%3E%3EP%3A%20changes%2042%20to%2057%2C%20cursor%2057%0A%20%20%20%20P-%3E%3EP%3A%20apply%20them%2C%20fork%20any%20workout%20edited%20on%20both%20sides%0A%20%20%20%20P-%3E%3ES%3A%20POST%20%2Fapi%2Fv1%2Fsync%2Fpush%20(the%20outbox)%0A%20%20%20%20S--%3E%3EP%3A%20200%2C%20or%20409%20stale-base%3A%20pull%20and%20try%20again%0A"})]),fallback:t(()=>[...e[1]||(e[1]=[i(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=n('<h3 id="when-it-runs" tabindex="-1">When it runs <a class="header-anchor" href="#when-it-runs" aria-label="Permalink to &quot;When it runs&quot;">​</a></h3><p>Only once the email is confirmed, and only while the app is open: when it opens, five seconds after a change, and on pull to refresh. Each run pulls first, then pushes. There is no background sync yet; it would need testing on real phones.</p><h3 id="pull" tabindex="-1">Pull <a class="header-anchor" href="#pull" aria-label="Permalink to &quot;Pull&quot;">​</a></h3><p><code>GET /api/v1/sync/pull?cursor=&lt;cursor&gt;&amp;limit=500</code> answers <code>{&quot;changes&quot;: [...], &quot;cursor&quot;: &quot;...&quot;, &quot;more&quot;: true}</code>. The phone keeps calling with the new cursor while <code>more</code> is true. With no cursor it gets everything, as a phone signing in does.</p><p>The cursor is a counter on the account, not a time. Every row the server writes for the account, a deletion included, takes the next number, under a lock on the account row, so two pushes never interleave their numbers and a pull never skips one. The phones&#39; clocks play no part.</p><p>A pull also returns the phone&#39;s own changes. Applying a change twice changes nothing, so the phone doesn&#39;t need to tell them apart. A plan, body measurement, setting or session header whose own change still waits in the outbox keeps the phone&#39;s value: the push that follows sends it, and the server keeps the later write.</p><h3 id="push" tabindex="-1">Push <a class="header-anchor" href="#push" aria-label="Permalink to &quot;Push&quot;">​</a></h3><p><code>POST /api/v1/sync/push</code> sends <code>{&quot;changes&quot;: [...]}</code>, at most 500 changes or 1 MB, oldest first. The phone keeps an outbox: each local write adds its change in the same transaction, and a push that is accepted removes what it carried. The profile, units and language live in the phone&#39;s small key-value store rather than its database, so their change is added just after the write instead. Nothing is added while the phone is a guest or its email is unconfirmed.</p><ul><li><strong>One push is one transaction</strong>: all of it is stored, or none of it.</li><li><strong>Every change is idempotent</strong>, so a push whose answer was lost is simply sent again.</li><li><strong>409 <code>stale-base</code></strong> names the workouts whose starting version is out of date. The phone pulls, forks them (below) and pushes again.</li><li><strong>400 <code>invalid-change</code></strong> gives the index of a change that doesn&#39;t parse or breaks a rule. The server checks workout content with the shared Kotlin types (<a href="./adr/0007-postgres-columns-for-structure-jsonb-for-content">ADR 0007</a>). The phone drops that change from its outbox, since it would be refused again and hold back the ones after it.</li></ul><h3 id="how-each-kind-of-change-merges" tabindex="-1">How each kind of change merges <a class="header-anchor" href="#how-each-kind-of-change-merges" aria-label="Permalink to &quot;How each kind of change merges&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Change</th><th>Carries</th><th>Merges</th></tr></thead><tbody><tr><td><code>workout-version</code></td><td>the <code>workout</code> as the shared Kotlin type (its id, <code>version</code>, name, format and parts), <code>baseVersion</code>, created at</td><td>Versions never change once made. The server takes version n + 1 only when its latest is n; the same version again with the same content changes nothing. Anything else is <code>stale-base</code>.</td></tr><tr><td><code>workout-deleted</code></td><td>workout id, the version deleted, when</td><td><strong>The edit wins.</strong> If another phone already pushed a newer version, the delete is ignored and the workout comes back on the phone that deleted it.</td></tr><tr><td><code>session</code></td><td>the session&#39;s header: id, source, workout id and version, start, end, name, format, totals</td><td>Only the phone that recorded a session writes it, so the latest push of its header wins.</td></tr><tr><td><code>session-events</code></td><td>session id, and events with their <code>seq</code>, time and payload</td><td>A union: an event already stored by <code>(session id, seq)</code> is skipped (<a href="./adr/0003-sessions-are-append-only-event-logs">ADR 0003</a>).</td></tr><tr><td><code>session-deleted</code></td><td>session id, when</td><td>Deletes the session and its events on every phone; it can&#39;t come back, since nobody else edits it.</td></tr><tr><td><code>planned-workout</code></td><td>id, workout id, day, created at, when the day was last set</td><td>The latest day wins.</td></tr><tr><td><code>planned-workout-deleted</code></td><td>id, when</td><td>The latest write wins, a move or the delete.</td></tr><tr><td><code>body-measurement</code></td><td>metric, day, value (or none, to delete), when</td><td>One per metric and day: the latest write wins, so two phones logging a weight the same day keep the later one.</td></tr><tr><td><code>setting</code></td><td>key, value (or none), when</td><td>The latest write wins per key. The keys are the profile&#39;s fields, units and language. Theme, app icon and paired devices aren&#39;t synced.</td></tr></tbody></table><p>The latest write is judged by the time the phone gives with the change. A phone with a wrong clock can lose a race on a small field, never a workout or a session.</p><h3 id="a-workout-edited-on-two-phones" tabindex="-1">A workout edited on two phones <a class="header-anchor" href="#a-workout-edited-on-two-phones" aria-label="Permalink to &quot;A workout edited on two phones&quot;">​</a></h3><p>Both phones made version 3 from version 2. The first push wins. The second phone gets <code>stale-base</code>, pulls the other version 3, and keeps its own edit as a copy:</p><ol><li>Its unsent versions of that workout become a new workout, with a new id, at version 1 with the latest of those edits, named after the phone: &quot;Leg day (Ana&#39;s iPhone)&quot;.</li><li>Its sessions and planned workouts that pointed at those unsent versions now point at the copy.</li><li>The outbox is rewritten to push the copy, and the push is sent again.</li></ol><p>Both phones then show both workouts, and nothing on the server is rewritten.</p><h3 id="signing-up-signing-in-and-out" tabindex="-1">Signing up, signing in and out <a class="header-anchor" href="#signing-up-signing-in-and-out" aria-label="Permalink to &quot;Signing up, signing in and out&quot;">​</a></h3><ul><li><strong>The first upload</strong> is the whole local database put in the outbox once the email is confirmed, with every id kept.</li><li><strong>Signing in on a phone with guest data</strong> pulls everything, then pushes the whole local database the same way. Ids never collide, so this is a union. Same-day body measurements and profile fields keep the latest write.</li><li><strong>Signing out</strong> with an empty outbox revokes the sign-in, then clears the workouts, sessions, planned workouts, body log, profile, units, language, the outbox and the cursor. With changes still in the outbox, the phone offers to wait or sign out anyway.</li><li><strong>When the server refuses the refresh token</strong>, the phone becomes a guest again and keeps its data, which happens after a password reset, the account&#39;s deletion or a revoked sign-in. Its outbox and cursor are cleared. Signing in again pushes everything once more, and nothing is duplicated.</li></ul><h2 id="what-follows-the-account" tabindex="-1">What follows the account <a class="header-anchor" href="#what-follows-the-account" aria-label="Permalink to &quot;What follows the account&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Follows the account</th><th>Stays on each phone</th></tr></thead><tbody><tr><td>Workouts, plans, enrollments, sessions</td><td>Theme</td></tr><tr><td>Profile and body log</td><td>App icon</td></tr><tr><td>Units and language</td><td>Paired treadmills and other devices</td></tr></tbody></table><h2 id="leaving" tabindex="-1">Leaving <a class="header-anchor" href="#leaving" aria-label="Permalink to &quot;Leaving&quot;">​</a></h2><ul><li><strong>Deleting the account happens at once</strong>, after the password: every row is deleted, every phone is signed out and goes back to a guest with its own copy, and the nightly dumps age out within 30 days.</li><li><strong>Export</strong> gives all the account&#39;s data as JSON, and sessions as FIT files.</li></ul><h2 id="screens" tabindex="-1">Screens <a class="header-anchor" href="#screens" aria-label="Permalink to &quot;Screens&quot;">​</a></h2><p>Drafted in <a href="https://github.com/tkint/coach-poulpy/issues/272" target="_blank" rel="noreferrer">#272</a>; they sit under Mockups, Drafts, Accounts on the site and are built once the owner has agreed them (<a href="./adr/0016-mockups-are-plain-html-in-the-repo">ADR 0016</a>).</p><ul><li><strong>Settings</strong> gets an <strong>Account</strong> section at the top. A guest sees one row, &quot;Sign in or create an account&quot;. With an unconfirmed email it reads &quot;Confirm your email&quot;; signed in it shows the address and the sync state. (<code>account-settings-guest</code>, <code>-pending</code>, <code>-synced</code>)</li><li><strong>Sign in is the default.</strong> The Account row in Settings opens Sign in: email, password, &quot;Forgot your password?&quot;, and a note that what is on the phone joins the account. One quiet line under it, &quot;No account yet? Create one&quot;, switches to <strong>Create your account</strong>, which asks for the email, a password (8 characters or more, with a show toggle) and the health data consent, whose link opens &quot;What is stored&quot;, and says &quot;Already have an account? Sign in&quot; to switch back. Errors sit under their field in <code>error</code> with an icon; a wrong email or password gives one message that doesn&#39;t say which. (<code>account-sign-in</code>, <code>-error</code>, <code>-reset-done</code>, <code>account-sign-up</code>, <code>-error</code>, <code>-offline</code>, <code>-consent-sheet</code>)</li><li><strong>Check your email</strong> has a single <strong>OK</strong> that returns to the app, which keeps working as a guest. Under it, two quiet lines: &quot;Didn&#39;t get the email? Send it again&quot; (signs up again with the same address) and &quot;Wrong address? Change it&quot; (reopens the form with the address filled in; nothing has left the phone, and the earlier address stays unconfirmed and is never used). The text never says whether the address already had an account: the server answers the same either way. An expired or used link has its own page. (<code>account-check-email</code>, <code>-resent</code>, <code>account-link-expired</code>)</li><li><strong>Email confirmed</strong> and <strong>Welcome back</strong> (signing in on a phone that has guest data) show the upload as a progress card; nothing is replaced, both edits are kept. (<code>account-confirmed</code>, <code>account-sign-in-merge</code>)</li><li><strong>Forgot your password?</strong> sends a link; it opens &quot;Choose a new password&quot;, every phone is signed out, and the next stop is Sign in with a &quot;Password changed&quot; note. (<code>account-forgot-password</code>, <code>-sent</code>, <code>account-reset-password</code>)</li><li><strong>The account page</strong> shows the address, the sync state, what follows the account, Export my data, Sign out and Delete account; before the email is confirmed it shows the same two quiet lines instead. (<code>account-details</code>, <code>-pending</code>)</li><li><strong>Sign out</strong> says the phone goes back to an empty guest. When changes aren&#39;t uploaded yet, a second dialog says they will never reach the account and offers &quot;Wait for the upload&quot; or &quot;Sign out anyway&quot;. (<code>account-sign-out</code>, <code>-unsent</code>)</li><li><strong>Delete account</strong> is a sheet that says what goes, asks for the password and deletes at once; a wrong password says nothing was deleted. (<code>account-delete</code>, <code>-error</code>)</li></ul><h2 id="not-yet" tabindex="-1">Not yet <a class="header-anchor" href="#not-yet" aria-label="Permalink to &quot;Not yet&quot;">​</a></h2><p>Apple and Google sign-in, the website&#39;s sign-in, sharing and coaching, and personal access tokens (<a href="https://github.com/tkint/coach-poulpy/issues/228" target="_blank" rel="noreferrer">#228</a>).</p>',27))])}const v=h(u,[["render",g]]);export{b as __pageData,v as default};
